description:
Write `final class Money` with a `long cents` and a `String currency` (both passed to the constructor), and override `equals`, `hashCode` and `toString` so that:

- two `Money` objects are equal when both fields are equal;
- equal objects have equal hash codes (use `Objects.hash`);
- `toString()` gives `"12.50 EUR"`;
- `equals(null)` and `equals("12.50 EUR")` are false.

starter.Money.java:
public final class Money {
    private final long cents;
    private final String currency;

    public Money(long cents, String currency) {
        this.cents = cents;
        this.currency = currency;
    }
}

solution.Money.java:
import java.util.Objects;

public final class Money {
    private final long cents;
    private final String currency;

    public Money(long cents, String currency) {
        this.cents = cents;
        this.currency = currency;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Money other)) return false;
        return cents == other.cents && currency.equals(other.currency);
    }

    @Override
    public int hashCode() {
        return Objects.hash(cents, currency);
    }

    @Override
    public String toString() {
        return String.format("%d.%02d %s", cents / 100, Math.abs(cents % 100), currency);
    }
}

unitTests:
test("equality", () -> {
    Money a = new Money(1250, "EUR");
    check(a.equals(new Money(1250, "EUR")), "same values should be equal");
    check(!a.equals(new Money(1250, "USD")), "different currencies are different");
    check(!a.equals(new Money(1251, "EUR")), "different amounts are different");
    check(!a.equals(null), "nothing equals null");
    check(!a.equals("12.50 EUR"), "a string is not Money");
    checkEq(a.hashCode(), new Money(1250, "EUR").hashCode());
});

test("works in hash collections", () -> {
    var set = new java.util.HashSet<Money>();
    set.add(new Money(500, "USD"));
    set.add(new Money(500, "USD"));
    checkEq(set.size(), 1);
    check(set.contains(new Money(500, "USD")), "the set should find an equal Money");
    var map = new java.util.HashMap<Money, String>();
    map.put(new Money(1, "GBP"), "penny");
    checkEq(map.get(new Money(1, "GBP")), "penny");
});

test("text", () -> {
    checkEq(new Money(1250, "EUR").toString(), "12.50 EUR");
    checkEq(new Money(7, "USD").toString(), "0.07 USD");
});

